const $=id=>document.getElementById(id),themes=window.WenareMapThemes,core=window.WenareOpportunities,colors=window.WenarePlacesMap.COLORS;
document.querySelector('.settings').open=!matchMedia('(max-width:650px)').matches;
const STYLE_URL='https://data.geopf.fr/annexes/ressources/vectorTiles/styles/PLAN.IGN/standard.json',DISTRICTS={poissy:{center:[2.0401,48.9325],zoom:14.2},paris:{center:[2.337,48.862],zoom:14.7}};
let map=null,lib=null,base=null,ready=false,theme='sobre',catalogue=null,markers=[],failed=false;
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
function message(text){$('mapMessage').textContent=text;$('mapMessage').hidden=!text;}
function settings(){return {original:$('original').checked,colors:Object.fromEntries(['water','park','road','building'].map(k=>[k,$(k+'Color').value])),roadWidth:Number($('roadWidth').value),labelSize:Number($('labelSize').value),labels:$('labels').checked,buildings:$('buildings').checked};}
function refreshLabels(){$('roadWidthValue').textContent=Number($('roadWidth').value).toLocaleString('fr-FR')+'×';$('labelSizeValue').textContent=Number($('labelSize').value).toLocaleString('fr-FR')+'×';$('customSettings').disabled=$('original').checked;$('mapTheme').textContent=$('original').checked?'Fond IGN original':'Ambiance '+themes.THEMES[theme].name;}
function apply(){refreshLabels();if(!ready)return;const target=themes.style(base,theme,settings());let count=0;try{for(const layer of target.layers){if(!map.getLayer(layer.id))continue;for(const [key,value] of Object.entries(layer.paint||{})){if(JSON.stringify(value)!==JSON.stringify(map.getPaintProperty(layer.id,key))){map.setPaintProperty(layer.id,key,value);count++;}}for(const key of (layer.type==='fill'?['fill-pattern','fill-color','fill-outline-color']:layer.type==='line'?['line-pattern','line-color','line-width']:layer.type==='symbol'?['text-color','text-halo-color']:[]))if(!(key in (layer.paint||{}))&&map.getPaintProperty(layer.id,key)!==undefined)map.setPaintProperty(layer.id,key,null);for(const key of ['visibility','text-size']){const value=layer.layout?.[key]??(key==='visibility'?'visible':undefined);if(value!==undefined&&JSON.stringify(map.getLayoutProperty(layer.id,key))!==JSON.stringify(value)){map.setLayoutProperty(layer.id,key,value);count++;}}}
$('evidenceText').textContent=$('original').checked?'Style IGN original, sur les mêmes données et au même cadrage. Décochez pour retrouver votre personnalisation.':'Style vectoriel personnalisé · '+target.layers.length+' couches disponibles. Eau, végétation, bâtiments, voies et noms sont dessinés séparément. Votre cadrage est conservé.';document.documentElement.dataset.theme=theme;document.documentElement.dataset.paintChanges=String(count);document.documentElement.dataset.labels=String($('labels').checked);map.triggerRepaint();}catch(e){message('Un réglage n’a pas pu être appliqué. Réinitialisez la carte.');console.error(e);}}
function setTheme(id){theme=id;document.body.dataset.theme=id;for(const b of document.querySelectorAll('[data-theme-choice]'))b.setAttribute('aria-pressed',String(b.dataset.themeChoice===id));const p=themes.THEMES[id];for(const k of ['water','park','road','building'])$(k+'Color').value=p[k];$('original').checked=false;apply();}
function showPlace(p){const c=core.CATEGORIES.find(c=>c.id===p.category);$('placeName').textContent=c.icon+' '+p.name;$('placeDescription').textContent=c.title+' · '+Math.round(p.distance).toLocaleString('fr-FR')+' m du centre du quartier'+(p.address?' · '+p.address:'')+'. '+c.limit+'.';const url=core.safeUrl(p.url);$('placeSource').href=url||'#';$('placeSource').hidden=!url;$('placeDetail').hidden=false;$('placeDetail').scrollIntoView({block:'nearest'});}
function drawPlaces(){for(const m of markers)m.remove();markers=[];$('legend').replaceChildren();$('placeDetail').hidden=true;if(!catalogue||!map||!ready||!$('wenarePlaces').checked){if(!$('wenarePlaces').checked)$('placesStatus').textContent='Repères WENARE masqués. Le fond IGN reste affiché.';return;}const district=DISTRICTS[$('district').value],p={lat:district.center[1],lon:district.center[0]};let total=0;for(const c of core.CATEGORIES.filter(c=>c.id!=='transport')){const rows=core.select(catalogue.items[c.id]||[],p,3000,Date.now(),2);if(!rows.length)continue;for(const place of rows){const b=el('button');b.type='button';b.className='poi-pin';b.style.setProperty('--category',colors[c.id]);b.title=c.title+' : '+place.name;b.setAttribute('aria-label',b.title);const body=el('span'),icon=el('b',c.icon);body.append(icon);b.append(body);b.onclick=()=>showPlace(place);markers.push(new lib.Marker({element:b,anchor:'bottom'}).setLngLat([place.lon,place.lat]).addTo(map));total++;}const s=el('span'),dot=el('i');dot.style.setProperty('--category',colors[c.id]);s.append(dot,el('span',c.short));$('legend').append(s);}$('placesStatus').textContent=total+' repères réels · sélection de démonstration : jusqu’à 2 par domaine à moins de 3 km du centre. Aucun lieu inventé.';}
for(const b of document.querySelectorAll('[data-theme-choice]'))b.onclick=()=>setTheme(b.dataset.themeChoice);
for(const id of ['waterColor','parkColor','roadColor','buildingColor','roadWidth','labelSize'])$(id).addEventListener('input',apply);
for(const id of ['original','labels','buildings'])$(id).onchange=apply;
$('wenarePlaces').onchange=drawPlaces;$('closeDetail').onclick=()=>{$('placeDetail').hidden=true;};
$('reset').onclick=()=>{$('roadWidth').value=$('labelSize').value='1';$('labels').checked=$('buildings').checked=true;setTheme(theme);};
function recenter(){if(map){const d=DISTRICTS[$('district').value];map.jumpTo({center:d.center,zoom:d.zoom,bearing:0,pitch:0});}}
$('recenter').onclick=recenter;$('north').onclick=()=>map?.jumpTo({bearing:0,pitch:0});$('district').onchange=()=>{recenter();drawPlaces();};
$('exportStyle').onclick=()=>{if(!base)return;const blob=new Blob([JSON.stringify(themes.style(base,theme,settings()),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='wenare-carte-'+($('original').checked?'ign-original':theme)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
async function loadCatalogue(){try{const root='../distribution/opportunities/',r=await fetch(root+'manifest.json',{signal:AbortSignal.timeout(20000)});if(!r.ok)throw new Error();const manifest=core.validateManifest(await r.json()),items={};await Promise.all(core.CATEGORIES.filter(c=>c.id!=='transport').map(async c=>{const meta=manifest.categories[c.id],response=await fetch(root+meta.file+'?v='+meta.sha256,{signal:AbortSignal.timeout(20000)});if(!response.ok)throw new Error();const bytes=await response.arrayBuffer(),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');if(bytes.byteLength!==meta.bytes||hash!==meta.sha256)throw new Error();items[c.id]=core.validatePayload(JSON.parse(new TextDecoder().decode(bytes)),c.id);if(items[c.id].length!==meta.count)throw new Error();}));catalogue={manifest,items};drawPlaces();}catch{$('placesStatus').textContent='Catalogue WENARE indisponible ou expiré. Vous pouvez comparer les fonds de carte sans repères.';}}
async function start(){refreshLabels();try{const [module,response]=await Promise.all([import('https://unpkg.com/maplibre-gl@6.17.0/dist/maplibre-gl.mjs'),fetch(STYLE_URL,{signal:AbortSignal.timeout(20000)})]);if(!response.ok)throw new Error('Fond IGN indisponible');lib=module;base=await response.json();if(base.version!==8||!Array.isArray(base.layers))throw new Error('Style IGN incompatible');const d=DISTRICTS.poissy;map=new lib.Map({container:'map',style:themes.style(base,theme,settings()),center:d.center,zoom:d.zoom,attributionControl:false,maxPitch:0,renderWorldCopies:false});map.addControl(new lib.AttributionControl({compact:true,customAttribution:'© IGN · Géoplateforme'}),'bottom-right');map.addControl(new lib.NavigationControl({showCompass:false}),'top-right');map.addControl(new lib.ScaleControl({unit:'metric'}),'bottom-left');map.on('error',e=>{if(e.error?.name==='GPUInitializationError'){failed=true;message('Ce navigateur ne permet pas le rendu WebGL2. Ouvrez ce prototype dans un navigateur récent.');}else if(!ready){message('Le fond IGN ou une ressource ne répond pas. Réessayez en rechargeant la page.');}});map.once('load',()=>{if(failed)return;ready=true;document.documentElement.dataset.mapReady='true';document.documentElement.dataset.engine='webgl';message('');$('exportStyle').disabled=false;apply();drawPlaces();});setTimeout(()=>{if(!ready&&!failed)message('Le chargement prend plus de temps que prévu. Vérifiez votre connexion ou rechargez la page.');},25000);loadCatalogue();}catch(e){if(e.name==='GPUInitializationError'&&base){message('Chargement du rendu vectoriel compatible…');try{const {canvasRenderer}=await import('./fallback.js?v=1'),result=await canvasRenderer(themes.style(base,theme,settings()));map=result.map;lib=result.lib;ready=true;document.documentElement.dataset.mapReady='true';document.documentElement.dataset.engine='canvas';$('exportStyle').disabled=false;result.raw.once('rendercomplete',()=>{message('');document.documentElement.dataset.mapRendered='true';});apply();loadCatalogue();return;}catch(fallbackError){console.error(fallbackError);}}failed=true;message('La carte n’a pas pu être chargée. Vérifiez votre connexion et rechargez la page.');$('placesStatus').textContent='Le prototype n’a pas modifié WENARE.';console.error(e);}}
start();
